.dev__tick--tall > span { height: 11px; }

.dev__rows { position: relative; margin-top: 4px; }
.dev__today {
  position: absolute;
  top: -2px;
  bottom: 34px;
  left: calc(300px + 26px + (100% - 300px - 170px - 52px) * 0.3);
  width: 1px;
  background: var(--accent);
  pointer-events: none;
  font-size: 12px;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--accent);
