  margin-top: clamp(28px, 4vh, 44px);
  background: rgba(var(--ink-rgb), 0.18);
}
.preloader__fill {
  display: block;
  width: 0;
  height: 1px;
  background: var(--accent);
  transition: width 0.25s linear;
}
.preloader__meta {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  margin-top: 14px;
  font-size: 12px;
  letter-spacing: 0.22em;
