  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: var(--accent);
}

.cmhead__meta { margin: 0; min-width: 0; font-size: 12px; font-weight: 300; color: rgba(var(--ink-rgb), 0.5); }

.cmhead__link {
  font-size: 12px;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--accent);
